css:
.hrai-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
    line-height: 1.45;
}

.hrai-sim-container .hrai-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 28px 32px;
    border-left: 6px solid #c9a14a;
    margin-bottom: 24px;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-header-eyebrow {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #c9a14a;
    margin-bottom: 8px;
    font-weight: 600;
}
.hrai-sim-container .hrai-sim-header h1 {
    font-size: 1.7rem;
    margin: 0 0 6px 0;
    font-weight: 600;
    letter-spacing: -0.01em;
}
.hrai-sim-container .hrai-sim-header-sub {
    font-size: 0.92rem;
    color: #b8c2d4;
    font-weight: 400;
}

.hrai-sim-container .hrai-sim-period-strip {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 16px 24px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 28px;
}
.hrai-sim-container .hrai-sim-period-block {
    display: flex;
    flex-direction: column;
    border-right: 1px solid #d8dde6;
    padding-right: 28px;
}
.hrai-sim-container .hrai-sim-period-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 4px;
}
.hrai-sim-container .hrai-sim-period-value {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-period-title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #1a2744;
}

.hrai-sim-container .hrai-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 18px 20px;
    border-radius: 2px;
    border-top: 3px solid #6b7689;
}
.hrai-sim-container .hrai-kpi-score {
    border-top-color: #c9a14a;
    background: linear-gradient(180deg, #ffffff 0%, #fbf6e8 100%);
}
.hrai-sim-container .hrai-sim-kpi-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 8px;
}
.hrai-sim-container .hrai-sim-kpi-value {
    font-size: 2.2rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.hrai-sim-container .hrai-kpi-score .hrai-sim-kpi-value {
    color: #8c6f1f;
}
.hrai-sim-container .hrai-sim-kpi-sub {
    font-size: 0.75rem;
    color: #6b7689;
    margin-top: 4px;
}

.hrai-sim-container .hrai-sim-cabinet-strip {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 18px 22px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-cabinet-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 14px;
}
.hrai-sim-container .hrai-sim-cabinet-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
}
.hrai-sim-container .hrai-sim-cabinet-card {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.hrai-sim-container .hrai-sim-cab-name {
    font-size: 0.82rem;
    font-weight: 600;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-cab-bar {
    height: 8px;
    background: #e6ebf2;
    border-radius: 4px;
    overflow: hidden;
}
.hrai-sim-container .hrai-sim-cab-fill {
    height: 100%;
    width: 50%;
    background: linear-gradient(90deg, #4a6a8a, #1a2744);
    transition: width 0.4s ease, background 0.4s ease;
}
.hrai-sim-container .hrai-sim-cab-pct {
    font-size: 0.78rem;
    color: #6b7689;
    font-weight: 600;
}

.hrai-sim-container .hrai-sim-briefing {
    background: #fbf6e8;
    border-left: 4px solid #c9a14a;
    padding: 20px 24px;
    margin-bottom: 24px;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-briefing-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #8c6f1f;
    font-weight: 700;
    margin-bottom: 10px;
}
.hrai-sim-container .hrai-sim-briefing-body {
    font-size: 0.95rem;
    color: #1a2744;
    line-height: 1.6;
}

.hrai-sim-container .hrai-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-controls h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    color: #1a2744;
    border-bottom: 2px solid #c9a14a;
    padding-bottom: 8px;
    display: inline-block;
}
.hrai-sim-container .hrai-sim-instructions {
    font-size: 0.88rem;
    color: #4a5468;
    margin: 14px 0 20px 0;
}

.hrai-sim-container .hrai-sim-pilot-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
}
.hrai-sim-container .hrai-sim-pilot-row {
    display: grid;
    grid-template-columns: 36px 1fr 220px;
    gap: 14px;
    align-items: center;
    padding: 12px 14px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-pilot-num {
    font-size: 0.85rem;
    font-weight: 700;
    color: #c9a14a;
    text-align: center;
}
.hrai-sim-container .hrai-sim-pilot-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
}
.hrai-sim-container .hrai-sim-pilot-name {
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-pilot-meta {
    font-size: 0.78rem;
    color: #6b7689;
}

.hrai-sim-container .hrai-sim-matrix-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
}
.hrai-sim-container .hrai-sim-matrix-row {
    display: grid;
    grid-template-columns: 36px 1fr 220px;
    gap: 14px;
    align-items: center;
    padding: 10px 14px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-matrix-cat {
    font-size: 0.9rem;
    font-weight: 500;
    color: #1a2744;
}

.hrai-sim-container .hrai-sim-select,
.hrai-sim-container select.hrai-sim-pilot-select,
.hrai-sim-container select.hrai-sim-matrix-select {
    background-color: #ffffff;
    color: #1a2744;
    border: 1px solid #b6bfd0;
    border-radius: 2px;
    padding: 7px 10px;
    font-size: 0.86rem;
    width: 100%;
    cursor: pointer;
}
.hrai-sim-container select.hrai-sim-pilot-select option,
.hrai-sim-container select.hrai-sim-matrix-select option,
.hrai-sim-container .hrai-sim-select option {
    background-color: #ffffff;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-select:focus,
.hrai-sim-container select:focus,
.hrai-sim-container input:focus {
    outline: 2px solid #c9a14a;
    outline-offset: 1px;
}

.hrai-sim-container .hrai-sim-r3-section {
    margin-bottom: 22px;
    padding-bottom: 18px;
    border-bottom: 1px dashed #d8dde6;
}
.hrai-sim-container .hrai-sim-r3-section:last-child {
    border-bottom: none;
    padding-bottom: 0;
    margin-bottom: 0;
}
.hrai-sim-container .hrai-sim-r3-label {
    display: block;
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 12px;
}
.hrai-sim-container .hrai-sim-checkbox-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 10px;
}
.hrai-sim-container .hrai-sim-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    padding: 10px 12px;
    border-radius: 2px;
    font-size: 0.86rem;
    color: #1a2744;
    cursor: pointer;
    margin: 0;
}
.hrai-sim-container .hrai-sim-check input[type="checkbox"] {
    margin-top: 2px;
    accent-color: #1a2744;
}

.hrai-sim-container .hrai-sim-action-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 28px;
}
.hrai-sim-container .hrai-sim-btn-primary {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #f4f5f7;
    font-weight: 600;
    padding: 11px 28px;
    border-radius: 2px;
    font-size: 0.92rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    transition: background 0.2s ease;
}
.hrai-sim-container .hrai-sim-btn-primary:hover {
    background: #c9a14a;
    border-color: #c9a14a;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-btn-secondary {
    border: 1px solid #b6bfd0;
    color: #4a5468;
    background: #ffffff;
    border-radius: 2px;
    padding: 9px 18px;
    font-size: 0.82rem;
}

.hrai-sim-container .hrai-sim-history,
.hrai-sim-container .hrai-sim-chart {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-section-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 700;
    margin-bottom: 14px;
}
.hrai-sim-container .hrai-sim-history table {
    margin-bottom: 0;
    font-size: 0.86rem;
}
.hrai-sim-container .hrai-sim-history th {
    background: #1a2744;
    color: #f4f5f7;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 10px 12px;
    border: none;
}
.hrai-sim-container .hrai-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #e6ebf2;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-chart canvas {
    max-height: 320px;
}

@media (max-width: 768px) {
    .hrai-sim-container { padding: 16px; }
    .hrai-sim-container .hrai-sim-header { padding: 20px; }
    .hrai-sim-container .hrai-sim-header h1 { font-size: 1.3rem; }
    .hrai-sim-container .hrai-sim-period-strip { flex-direction: column; align-items: flex-start; gap: 10px; }
    .hrai-sim-container .hrai-sim-period-block { border-right: none; padding-right: 0; }
    .hrai-sim-container .hrai-sim-pilot-row,
    .hrai-sim-container .hrai-sim-matrix-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }
    .hrai-sim-container .hrai-sim-kpi-value { font-size: 1.6rem; }
}

/* v1.1.0 additions: accessible focus ring + completion summary */
.hrai-sim-container :is(select, input, button, textarea):focus-visible { outline: 3px solid #2f6f4f; outline-offset: 2px; }
.hrai-completion { padding: 8px 4px; text-align: center; }
.hrai-completion-title { margin: 0 0 12px; font-size: 1.4rem; }
.hrai-completion-score { margin: 6px 0 16px; }
.hrai-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; }
.hrai-completion-score .acs-max { font-size: 1.1rem; opacity: .7; margin-left: 2px; }
.hrai-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; opacity: .7; margin-top: 2px; }
.hrai-completion-rating { margin: 8px auto 14px; max-width: 580px; line-height: 1.5; font-weight: 600; }
.hrai-completion-takeaways { text-align: left; max-width: 660px; margin: 6px auto 0; }
.hrai-completion-takeaways h4 { font-size: .95rem; margin: 0 0 8px; }
.hrai-completion-takeaways ul { margin: 0; padding-left: 20px; }
.hrai-completion-takeaways li { margin-bottom: 6px; line-height: 1.45; }
.hrai-completion-thanks { font-size: .85rem; opacity: .75; margin-top: 16px; }

js:
(function() {
    'use strict';

    class HrAiOperatingModelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'AI in HR Operating Model';
            this.version = '1.1.0';

            this.PILOTS = [
                { num: 1,  key: 'p1',  defensible: 'scale',   crit: true,  meta: 'Eightfold · USD 1.1M · Esteban · live CR & MX · time-to-shortlist −38% · adverse-impact signal in MX plant pipeline' },
                { num: 2,  key: 'p2',  defensible: 'scale',   crit: true,  meta: 'Paradox + custom · USD 0.7M · Esteban · live all geos · recruiter throughput +22% · no material concern' },
                { num: 3,  key: 'p3',  defensible: 'rescope', crit: true,  meta: 'Workday Extend + OpenAI · USD 0.9M · Federico · live CR · 31% manager time saving · drafts appearing verbatim' },
                { num: 4,  key: 'p4',  defensible: 'kill',    crit: true,  meta: 'Same vendor stack · USD 0.4M · Esteban · paused after Brazilian works-council complaint' },
                { num: 5,  key: 'p5',  defensible: 'rescope', crit: true,  meta: 'Visier + custom · USD 0.6M · Ileana · live CR & ES · model uses email-metadata features (EU AI Act exposure)' },
                { num: 6,  key: 'p6',  defensible: 'scale',   crit: true,  meta: 'ServiceNow HRSD · USD 1.3M · Ileana · live all geos · ticket volume −47% · NPS +11 · no concern' },
                { num: 7,  key: 'p7',  defensible: 'rescope', crit: true,  meta: 'ServiceNow + ES-LLM layer · USD 0.5M · Ileana · live CR · ticket load −38% · CR retirement-fund misanswer triggered formal complaint' },
                { num: 8,  key: 'p8',  defensible: 'rescope', crit: false, meta: 'Eightfold · USD 0.8M · Esteban · live CR corporate · internal-fill 31→38% · clustering bias on English speakers' },
                { num: 9,  key: 'p9',  defensible: 'kill',    crit: true,  meta: 'Gloat · USD 1.4M · Esteban · live ES · 8% engagement at 90 days · duplicates pilot 8 and pilot 10' },
                { num: 10, key: 'p10', defensible: 'scale',   crit: false, meta: 'Eightfold marketplace module · USD 0.9M · Esteban · 400-FTE CR pilot · 22% engagement · also duplicative · pick survivor' },
                { num: 11, key: 'p11', defensible: 'kill',    crit: true,  meta: 'CR startup (Esteban brother-in-law) · USD 0.3M · UNSANCTIONED · GDPR-equivalent exposure ES · no employee consent · conflict of interest' }
            ];

            this.MATRIX = [
                { num: 1,  key: 'm1',  defensible: 'led',  meta: 'Recruiting — top-of-funnel sourcing & screening' },
                { num: 2,  key: 'm2',  defensible: 'led',  meta: 'Recruiting — middle-of-funnel candidate engagement' },
                { num: 3,  key: 'm3',  defensible: 'aug',  meta: 'Recruiting — offer-stage construction & negotiation' },
                { num: 4,  key: 'm4',  defensible: 'led',  meta: 'Onboarding — administrative provisioning' },
                { num: 5,  key: 'm5',  defensible: 'human',meta: 'Onboarding — cultural integration & first-90-days' },
                { num: 6,  key: 'm6',  defensible: 'aug',  meta: 'Performance — narrative drafting' },
                { num: 7,  key: 'm7',  defensible: 'aug',  meta: 'Performance — calibration discussions' },
                { num: 8,  key: 'm8',  defensible: 'aug',  meta: 'Compensation — modelling & decision support' },
                { num: 9,  key: 'm9',  defensible: 'human',meta: 'Compensation — final pay decision authority' },
                { num: 10, key: 'm10', defensible: 'aug',  meta: 'Manager enablement — feedback synthesis' },
                { num: 11, key: 'm11', defensible: 'led',  meta: 'Employee Q&A — policy & benefits (Tier 1)' },
                { num: 12, key: 'm12', defensible: 'human',meta: 'Employee escalations (Tier 2/3) — grievances, ER' },
                { num: 13, key: 'm13', defensible: 'aug',  meta: 'Terminations — case preparation & documentation' },
                { num: 14, key: 'm14', defensible: 'human',meta: 'Terminations — execution conversation' },
                { num: 15, key: 'm15', defensible: 'led',  meta: 'Learning — content curation & path recommendation' },
                { num: 16, key: 'm16', defensible: 'aug',  meta: 'Learning — coaching interactions' },
                { num: 17, key: 'm17', defensible: 'led',  meta: 'Exit interviews — synthesis & theme extraction' },
                { num: 18, key: 'm18', defensible: 'led',  meta: 'Retention — risk modelling & alerting' },
                { num: 19, key: 'm19', defensible: 'aug',  meta: 'Internal mobility — recommendations & matching' }
            ];

            this.ROUND_TITLES = ['r1_title', 'r2_title', 'r3_title'];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    auditScore: 0,
                    matrixScore: 0,
                    archScore: 0,
                    totalScore: 0,
                    ceoSupport: 50,
                    cooSupport: 50,
                    cfoSupport: 50,
                    boardSupport: 50,
                    councilSupport: 50,
                    scoreHistory: [],
                    ceoHistory: [],
                    cooHistory: [],
                    cfoHistory: [],
                    boardHistory: [],
                    councilHistory: [],
                    pilots: {},
                    matrix: {},
                    vendorArch: '',
                    buildEnvelope: [],
                    changePlan: [],
                    lastFeedback: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { round: 1, summary: '' };
            }
            this._renderInputs();
            this._updateBriefing(state);
            this._updateCabinetBars(state.domainState);
        }

        _renderInputs() {
            var pilotGrid = document.getElementById('pilotGrid');
            if (pilotGrid && pilotGrid.children.length === 0) {
                var html = '';
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    html += '<div class="hrai-sim-pilot-row">';
                    html += '<div class="hrai-sim-pilot-num">#' + p.num + '</div>';
                    html += '<div class="hrai-sim-pilot-info">';
                    html += '<div class="hrai-sim-pilot-name" data-i18n="pilot_' + p.num + '_name"></div>';
                    html += '<div class="hrai-sim-pilot-meta">' + p.meta + '</div>';
                    html += '</div>';
                    html += '<select class="hrai-sim-pilot-select" id="pilot_' + p.num + '">';
                    html += '<option value="" data-i18n="opt_choose">— choose —</option>';
                    html += '<option value="kill" data-i18n="opt_kill">Kill</option>';
                    html += '<option value="scale" data-i18n="opt_scale">Scale</option>';
                    html += '<option value="rescope" data-i18n="opt_rescope">Re-scope</option>';
                    html += '<option value="hold" data-i18n="opt_hold">Hold pending review</option>';
                    html += '</select>';
                    html += '</div>';
                }
                pilotGrid.innerHTML = html;
            }

            var matrixGrid = document.getElementById('matrixGrid');
            if (matrixGrid && matrixGrid.children.length === 0) {
                var mhtml = '';
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    mhtml += '<div class="hrai-sim-matrix-row">';
                    mhtml += '<div class="hrai-sim-pilot-num">' + m.num + '</div>';
                    mhtml += '<div class="hrai-sim-matrix-cat" data-i18n="cat_' + m.num + '">' + m.meta + '</div>';
                    mhtml += '<select class="hrai-sim-matrix-select" id="cat_' + m.num + '">';
                    mhtml += '<option value="" data-i18n="opt_choose">— choose —</option>';
                    mhtml += '<option value="led" data-i18n="opt_led">Agent-led</option>';
                    mhtml += '<option value="aug" data-i18n="opt_aug">Agent-augmented</option>';
                    mhtml += '<option value="human" data-i18n="opt_human">Human-only</option>';
                    mhtml += '</select>';
                    mhtml += '</div>';
                }
                matrixGrid.innerHTML = mhtml;
            }
        }

        validateDecisions(decisions) {
            var period = (window.mySimulation.state.currentPeriod) || 1;
            decisions.round = period;

            if (period === 1) {
                var allSet = true;
                var pilotChoices = {};
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    var sel = document.getElementById('pilot_' + p.num);
                    if (!sel || !sel.value) { allSet = false; break; }
                    pilotChoices[p.num] = sel.value;
                }
                if (!allSet) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_all_pilots'), 'warning'
                    );
                    return false;
                }
                decisions.pilotChoices = pilotChoices;
                return true;
            }

            if (period === 2) {
                var allSetM = true;
                var matrixChoices = {};
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    var ms = document.getElementById('cat_' + m.num);
                    if (!ms || !ms.value) { allSetM = false; break; }
                    matrixChoices[m.num] = ms.value;
                }
                if (!allSetM) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_all_matrix'), 'warning'
                    );
                    return false;
                }
                decisions.matrixChoices = matrixChoices;
                return true;
            }

            if (period === 3) {
                var vsel = document.getElementById('vendorArchSelect');
                if (!vsel || !vsel.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_vendor'), 'warning'
                    );
                    return false;
                }
                decisions.vendorArch = vsel.value;

                var buildIds = ['buildPerf','buildBenefits','buildOnboarding','buildCalibration','buildExit','buildEthics','buildMobility','buildSafety'];
                var build = [];
                for (var k = 0; k < buildIds.length; k++) {
                    var c = document.getElementById(buildIds[k]);
                    if (c && c.checked) build.push(c.value);
                }
                decisions.buildEnvelope = build;

                var cpIds = ['cpRecruiter','cpTier1','cpHRBP','cpAnalytics','cpEthicsLead','cpMarisol','cpNoNewPilots'];
                var cp = [];
                for (var l = 0; l < cpIds.length; l++) {
                    var cc = document.getElementById(cpIds[l]);
                    if (cc && cc.checked) cp.push(cpIds[l]);
                }
                decisions.changePlan = cp;
                return true;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundScore = 0;
            var feedback = '';
            var ceoDelta = 0, cooDelta = 0, cfoDelta = 0, boardDelta = 0, councilDelta = 0;
            var killedAny = false;
            var killedP11 = false;
            var killedDuplicate = false;
            var rightCount = 0;

            if (period === 1) {
                ds.pilots = d.pilotChoices || {};
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    var choice = ds.pilots[p.num];
                    if (choice === p.defensible) {
                        roundScore += p.crit ? 4 : 3;
                        rightCount += 1;
                    } else if (choice === 'hold') {
                        roundScore += 0;
                        boardDelta -= 2;
                    } else if (choice === 'kill' && p.defensible !== 'kill') {
                        roundScore += 1;
                    } else {
                        roundScore += 1;
                    }
                    if (choice === 'kill') killedAny = true;
                    if (p.num === 11 && choice === 'kill') killedP11 = true;
                    if ((p.num === 9 || p.num === 10) && choice === 'kill') killedDuplicate = true;
                }
                if (killedP11) { boardDelta += 12; cfoDelta += 6; ceoDelta -= 3; councilDelta += 4; feedback = 'P11 killed: conflict-of-interest cleared.'; }
                else { boardDelta -= 10; cfoDelta -= 6; feedback = 'P11 left alive — Don Eugenio will find it on page two of his briefing.'; }
                if (killedDuplicate) { cfoDelta += 6; ceoDelta += 2; }
                else { cfoDelta -= 4; }
                if (!killedAny) { boardDelta -= 8; ceoDelta -= 4; feedback += ' No pilots killed — operating-model authority not yet earned.'; }
                if (rightCount >= 9) { ceoDelta += 4; cooDelta += 3; }
                ds.auditScore = Math.round((roundScore / 41) * 100);
                if (ds.auditScore > 100) ds.auditScore = 100;
            }

            else if (period === 2) {
                ds.matrix = d.matrixChoices || {};
                var ledCount = 0, augCount = 0, humanCount = 0;
                var correctLockouts = 0;
                var lockoutCats = [5, 9, 12, 14];
                var ledHits = 0;
                var ledTargets = [1,2,4,11,15,17,18];
                var totalRight = 0;
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    var cc = ds.matrix[m.num];
                    if (cc === 'led') ledCount += 1;
                    else if (cc === 'aug') augCount += 1;
                    else if (cc === 'human') humanCount += 1;
                    if (cc === m.defensible) {
                        roundScore += 3;
                        totalRight += 1;
                        if (lockoutCats.indexOf(m.num) >= 0) correctLockouts += 1;
                        if (ledTargets.indexOf(m.num) >= 0) ledHits += 1;
                    }
                }
                if (ledCount > 11) { ceoDelta += 3; boardDelta -= 12; cooDelta -= 6; feedback = 'Eleven-plus agent-led categories — Don Eugenio reads it as a slogan, not an operating model.'; }
                else if (ledCount < 2) { boardDelta -= 4; cfoDelta -= 10; ceoDelta -= 6; feedback = 'Two-or-fewer agent-led categories — Mariana concludes you are not serious about the AI agenda.'; }
                else { ceoDelta += 4; cfoDelta += 6; }
                if (correctLockouts === 4) { boardDelta += 14; councilDelta += 12; feedback += ' Lockouts (categories 5, 9, 12, 14) named correctly — the most important column on the page.'; }
                else if (correctLockouts >= 2) { boardDelta += 4; councilDelta += 4; }
                else { boardDelta -= 8; councilDelta -= 8; feedback += ' Human-only column thin — the matrix earns its credibility from the lockouts it names.'; }
                if (ledHits >= 5) { cfoDelta += 6; ceoDelta += 4; cooDelta += 4; }
                if (totalRight >= 15) { ceoDelta += 4; cooDelta += 4; }
                ds.matrixScore = Math.round((roundScore / 57) * 100);
                if (ds.matrixScore > 100) ds.matrixScore = 100;
            }

            else if (period === 3) {
                ds.vendorArch = d.vendorArch || '';
                ds.buildEnvelope = d.buildEnvelope || [];
                ds.changePlan = d.changePlan || [];

                if (ds.vendorArch === 'hub') { roundScore += 25; cfoDelta += 8; ceoDelta += 6; cooDelta += 6; boardDelta += 6; feedback = 'Hub-and-spoke architecture committed — vendor count is the architectures unit of measure (Bhusri).'; }
                else if (ds.vendorArch === 'single') { roundScore += 14; cfoDelta += 12; cooDelta -= 4; feedback = 'Single-stack consolidation — Mariana likes the bill, Rodrigo gives up best-of-breed.'; }
                else if (ds.vendorArch === 'federated') { roundScore += 6; cfoDelta -= 12; boardDelta -= 6; cooDelta -= 6; feedback = 'Best-of-breed federation — six vendors is six governance regimes (Bhusri would push back).'; }

                var bSize = ds.buildEnvelope.length;
                var bHasPerf = ds.buildEnvelope.indexOf('perf') >= 0;
                var bHasBenefits = ds.buildEnvelope.indexOf('benefits') >= 0;
                if (bSize >= 2 && bSize <= 3) { roundScore += 18; cfoDelta += 4; cooDelta += 4; feedback += ' Build envelope bounded — we will build that ourselves stops being the default answer.'; }
                else if (bSize >= 4 && bSize <= 5) { roundScore += 10; cfoDelta -= 2; }
                else if (bSize >= 6) { roundScore += 4; cfoDelta -= 8; cooDelta -= 4; feedback += ' Build envelope unbounded — Federico will absorb the agenda.'; }
                else if (bSize === 1) { roundScore += 6; }
                else { roundScore += 2; cooDelta -= 4; }
                if (bHasPerf && bHasBenefits) { roundScore += 4; }

                var cpHas = function(k) { return ds.changePlan.indexOf(k) >= 0; };
                var shrinkNamed = (cpHas('cpRecruiter') ? 1 : 0) + (cpHas('cpTier1') ? 1 : 0);
                if (shrinkNamed === 2) { roundScore += 14; councilDelta += 8; boardDelta += 6; feedback += ' Change plan names what shrinks — Marisol reads the bad news.'; }
                else if (shrinkNamed === 1) { roundScore += 7; councilDelta += 2; }
                else { councilDelta -= 12; boardDelta -= 6; feedback += ' Change plan names no shrinkage — Marisol concludes the operating model has no real consequences.'; }
                if (cpHas('cpEthicsLead')) { roundScore += 4; boardDelta += 4; }
                if (cpHas('cpAnalytics')) { roundScore += 3; ceoDelta += 2; }
                if (cpHas('cpHRBP')) { roundScore += 2; }
                if (cpHas('cpMarisol')) { roundScore += 5; councilDelta += 10; feedback += ' Draft shared with Marisol before Audit Committee — she will give you a real read.'; }
                else { councilDelta -= 6; }
                if (cpHas('cpNoNewPilots')) { roundScore += 6; boardDelta += 6; ceoDelta -= 2; feedback += ' No-new-pilots commitment — Andrés will need to defend it personally.'; }

                ds.archScore = Math.round((roundScore / 79) * 100);
                if (ds.archScore > 100) ds.archScore = 100;
            }

            ds.ceoSupport = Math.max(0, Math.min(100, ds.ceoSupport + ceoDelta));
            ds.cooSupport = Math.max(0, Math.min(100, ds.cooSupport + cooDelta));
            ds.cfoSupport = Math.max(0, Math.min(100, ds.cfoSupport + cfoDelta));
            ds.boardSupport = Math.max(0, Math.min(100, ds.boardSupport + boardDelta));
            ds.councilSupport = Math.max(0, Math.min(100, ds.councilSupport + councilDelta));

            var components = [];
            if (ds.auditScore) components.push(ds.auditScore);
            if (ds.matrixScore) components.push(ds.matrixScore);
            if (ds.archScore) components.push(ds.archScore);
            var avg = components.length ? components.reduce(function(s,v){ return s+v; },0) / components.length : 0;
            var cabinetAvg = (ds.ceoSupport + ds.cooSupport + ds.cfoSupport + ds.boardSupport + ds.councilSupport) / 5;
            ds.totalScore = Math.round(avg * 0.6 + cabinetAvg * 0.4);

            ds.scoreHistory.push(ds.totalScore);

            // v1.1.0 FIX: persist the 0-100 operating-model score so the instructor results panel
            // (results_utils.php express_resolveDomainScore -> domainState.performance.overallScore)
            // shows a real score instead of "-". Additive; scoring logic unchanged.
            ds.performance = { overallScore: ds.totalScore };
            ds.ceoHistory.push(ds.ceoSupport);
            ds.cooHistory.push(ds.cooSupport);
            ds.cfoHistory.push(ds.cfoSupport);
            ds.boardHistory.push(ds.boardSupport);
            ds.councilHistory.push(ds.councilSupport);
            ds.lastFeedback = feedback;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
                self._updateCabinetBars(ds);
            }, 350);

            return {
                period: period,
                roundScore: roundScore,
                auditScore: ds.auditScore,
                matrixScore: ds.matrixScore,
                archScore: ds.archScore,
                totalScore: ds.totalScore,
                feedback: feedback,
                ceoSupport: ds.ceoSupport,
                cooSupport: ds.cooSupport,
                cfoSupport: ds.cfoSupport,
                boardSupport: ds.boardSupport,
                councilSupport: ds.councilSupport
            };
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 2);
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.setAttribute('data-i18n', this.ROUND_TITLES[idx]);
                if (window.mySimulation && window.mySimulation.t) {
                    titleEl.textContent = window.mySimulation.t(this.ROUND_TITLES[idx]);
                }
            }
            var brief = document.getElementById('briefingText');
            if (brief && window.mySimulation && window.mySimulation.t) {
                var keys = ['briefing_r1','briefing_r2','briefing_r3','briefing_done'];
                var k = period > 3 ? keys[3] : keys[idx];
                brief.innerHTML = window.mySimulation.t(k);
            }
            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            if (r1) r1.style.display = (period === 1) ? 'block' : 'none';
            if (r2) r2.style.display = (period === 2) ? 'block' : 'none';
            if (r3) r3.style.display = (period === 3) ? 'block' : 'none';
        }

        _updateCabinetBars(ds) {
            var pairs = [
                ['ceoBar','ceoPct',ds.ceoSupport],
                ['cooBar','cooPct',ds.cooSupport],
                ['cfoBar','cfoPct',ds.cfoSupport],
                ['boardBar','boardPct',ds.boardSupport],
                ['councilBar','councilPct',ds.councilSupport]
            ];
            for (var i = 0; i < pairs.length; i++) {
                var bar = document.getElementById(pairs[i][0]);
                var pct = document.getElementById(pairs[i][1]);
                var v = pairs[i][2];
                if (bar) {
                    bar.style.width = v + '%';
                    var color = v >= 65 ? 'linear-gradient(90deg, #2d6a4f, #52b788)'
                              : v >= 45 ? 'linear-gradient(90deg, #4a6a8a, #1a2744)'
                              : v >= 25 ? 'linear-gradient(90deg, #c9a14a, #a8841d)'
                              : 'linear-gradient(90deg, #b03030, #8a1f1f)';
                    bar.style.background = color;
                }
                if (pct) pct.textContent = v + '%';
            }
        }

